INSERT INTO `announcements` VALUES (1,'OAS Office Closed on November 5','The Office of Admission and Scholarship will be closed on Thursday, November 5, 2026. Online applications in ScholarGuide stay open. Messages sent through Contact OAS will be answered on the next working day.','/announcements/office-closed.jpg',2,'2026-11-21 12:45:27','2026-11-05','2026-11-21 12:45:27','2026-11-21 12:45:27'),(2,'Payroll Schedule for 1st Semester','OAS is preparing the payroll for active grantees whose enrollment has been verified for the 1st Semester AY 2026-2027. The payout date will be posted here once the funding agency releases it. Grantees without an ATM card yet should message OAS through Contact OAS.','/announcements/payroll-schedule.jpg',2,'2026-11-20 12:45:27',NULL,'2026-11-21 12:45:27','2026-11-21 12:45:27'),(3,'Congratulations to New Scholars','Congratulations to the students who were approved this semester! Please check My Applications: OAS will verify your enrollment and tag you as a grantee. Keep your contact number in My Profile up to date.','/announcements/new-scholars.jpg',2,'2026-11-18 12:45:27','2026-11-30','2026-11-21 12:45:27','2026-11-21 12:45:27'),(4,'Agency-Direct Scholarships: Apply at the Agency','Iskolar ng Landbank, DA-ACEF, ACEF-GIAHEP, DOST, LGU-Bayugan Graduate School, NGCP and Enfants du Mekong scholarships are agency-direct. Submit your application directly to the scholarship-giving agency and transact requirements and allowances with its office. The OAS posts announcements and updates when an agency requests it.','/announcements/orientation.jpg',2,'2026-11-16 12:45:27','2026-10-24','2026-11-21 12:45:27','2026-11-21 12:45:27'),(5,'Reminder: TES and TDP-TES Deadline','Applications for the CHED Tertiary Education Subsidy (TES) and the CHED Tulong-Dunong Program (TDP-TES) close on October 31, 2026 (demo date). Drafts that are not submitted by the deadline can no longer be submitted, so press Submit application once every required document is uploaded.','/announcements/deadline-extended.jpg',2,'2026-11-15 12:45:27','2026-10-31','2026-11-21 12:45:27','2026-11-21 12:45:27'),(6,'Culture and Arts Financial Assistance','Members of CSU culture and arts groups may apply for the university-funded Culture and Arts financial assistance until November 15, 2026 (demo date). Prepare your COR, Certificate of Grades, Valid ID, Birth Certificate, Certificate of Good Moral Character and a recommendation letter from your group\'s adviser.','/announcements/cultural-auditions.jpg',2,'2026-11-11 12:45:27','2026-11-15','2026-11-21 12:45:27','2026-11-21 12:45:27'),(7,'DOST Scholarship Updates','The DOST scholarship is agency-direct: applications and allowances are handled by DOST. This notice has expired and is shown only to staff.','/announcements/science-slots.jpg',2,'2026-09-02 12:45:27','2026-08-14','2026-11-21 12:45:27','2026-11-21 12:45:27'),(8,'CHED Merit Scholarship Now Open','Applications for the CHED Merit Scholarship Program (CMSP), Full SSP and Half SSP, were open until August 31, 2026 (demo date). This notice has expired and is shown only to staff.','/announcements/scholarship-open.jpg',2,'2026-08-28 12:45:27','2026-08-31','2026-11-21 12:45:27','2026-11-21 12:45:27');
/*!40000 ALTER TABLE `announcements` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `application_status_logs`
--

DROP TABLE IF EXISTS `application_status_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `application_status_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `application_id` bigint(20) unsigned NOT NULL,
  `from_status` varchar(30) DEFAULT NULL,
  `to_status` varchar(30) NOT NULL,
  `remarks` text DEFAULT NULL,
  `changed_by` bigint(20) unsigned DEFAULT NULL,
  `read_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `application_status_logs_changed_by_foreign` (`changed_by`),
  KEY `application_status_logs_application_id_created_at_index` (`application_id`,`created_at`),
  CONSTRAINT `application_status_logs_application_id_foreign` FOREIGN KEY (`application_id`) REFERENCES `applications` (`id`) ON DELETE CASCADE,
  CONSTRAINT `application_status_logs_changed_by_foreign` FOREIGN KEY (`changed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1162 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `application_status_logs`
--

LOCK TABLES `application_status_logs` WRITE;
/*!40000 ALTER TABLE `application_status_logs` DISABLE KEYS */;
