--
-- Table structure for table `applications`
--

DROP TABLE IF EXISTS `applications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `applications` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `student_id` bigint(20) unsigned NOT NULL,
  `scholarship_id` bigint(20) unsigned NOT NULL,
  `school_year` varchar(9) DEFAULT NULL,
  `status` enum('draft','submitted','under_review','needs_action','complete','approved','rejected') NOT NULL DEFAULT 'draft',
  `remarks` text DEFAULT NULL,
  `agency_control_number` varchar(20) DEFAULT NULL,
  `agency_award_number` varchar(60) DEFAULT NULL,
  `agency_amount` decimal(12,2) DEFAULT NULL,
  `agency_batch` varchar(30) DEFAULT NULL,
  `agency_list_upload_id` bigint(20) unsigned DEFAULT NULL,
  `submitted_at` timestamp NULL DEFAULT NULL,
  `forwarded_at` timestamp NULL DEFAULT NULL,
  `enrollment_verified` tinyint(1) NOT NULL DEFAULT 0,
  `enrollment_verified_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `applications_one_per_program_per_year` (`student_id`,`scholarship_id`,`school_year`),
  KEY `applications_scholarship_id_foreign` (`scholarship_id`),
  KEY `applications_agency_list_upload_id_foreign` (`agency_list_upload_id`),
  CONSTRAINT `applications_agency_list_upload_id_foreign` FOREIGN KEY (`agency_list_upload_id`) REFERENCES `agency_list_uploads` (`id`) ON DELETE SET NULL,
  CONSTRAINT `applications_scholarship_id_foreign` FOREIGN KEY (`scholarship_id`) REFERENCES `scholarships` (`id`) ON DELETE CASCADE,
  CONSTRAINT `applications_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=263 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `applications`
--

LOCK TABLES `applications` WRITE;
/*!40000 ALTER TABLE `applications` DISABLE KEYS */;
