INSERT INTO `contact_messages` VALUES (1,5,'documents','Barangay clearance is still being processed','Good day po. My barangay clearance will only be released next week. Can I submit my application first and upload it later?','open',NULL,NULL,NULL,NULL,'2026-11-19 12:45:27','2026-11-19 12:45:27'),(2,7,'payroll','No ATM card yet','I was tagged as a grantee but I do not have an ATM card yet. Where should I apply for one?','open',NULL,NULL,NULL,NULL,'2026-11-20 12:45:27','2026-11-20 12:45:27'),(3,10,'application','Status says Needs action','What does Needs action mean on my application?','answered','It means OAS found something to fix. Open the application to read the remarks, upload the corrected file and press Submit again.',2,'2026-11-17 12:45:27','2026-11-17 12:45:27','2026-11-16 12:45:27','2026-11-16 12:45:27');
